const docs = [];
for (const item of $input.all()) {
  const o = item.json;
  const lineItems = (o.line_items || []).map(li => `${li.title} x${li.quantity}`).join(', ');
  const tracking = (o.fulfillments || []).map(f => f.tracking_number).filter(Boolean).join(', ') || 'N/A';
  docs.push({ json: {
    text: `Order ${o.name} | Platform: Shopify | Customer: ${o.email || 'N/A'} | Products: ${lineItems || 'N/A'} | Total: ${o.currency} ${o.total_price} | Status: ${o.fulfillment_status || 'unfulfilled'} | Financial: ${o.financial_status} | Tracking: ${tracking} | Created: ${o.created_at}`,
    metadata: {
      id: `shopify-order-${o.id}`,
      platform: 'shopify',
      type: 'order',
      source: 'live',
      orderId: String(o.name),
      customer: o.email || '',
      status: o.fulfillment_status || 'unfulfilled',
      financialStatus: o.financial_status || '',
      total: String(o.total_price || ''),
      currency: o.currency || 'USD'
    }
  }});
}
return docs;

const docs = [];
for (const item of $input.all()) {
  const p = item.json;
  const desc = (p.body_html || '').replace(/<[^>]*>/g, '').substring(0, 300);
  const variants = (p.variants || []).map(v => `${v.title}: $${v.price} SKU:${v.sku || 'N/A'} Stock:${v.inventory_quantity ?? 'N/A'}`).join('; ');
  docs.push({ json: {
    text: `Product: ${p.title} | Platform: Shopify | Type: ${p.product_type || 'N/A'} | Vendor: ${p.vendor || 'N/A'} | Description: ${desc || 'N/A'} | Variants: ${variants || 'N/A'} | Tags: ${p.tags || 'N/A'}`,
    metadata: {
      id: `shopify-product-${p.id}`,
      platform: 'shopify',
      type: 'product',
      source: 'live',
      productId: String(p.id),
      title: p.title || '',
      vendor: p.vendor || '',
      productType: p.product_type || '',
      tags: p.tags || ''
    }
  }});
}
return docs;

const docs = [];

const amazonOrders = [
  { orderId: 'AMZ-10011', customer: 'Sarah Mitchell', products: 'Omega-3 Fish Oil 1000mg x2', total: '49.98', status: 'delivered' },
  { orderId: 'AMZ-10022', customer: 'David Kim', products: 'Vitamin D3 5000IU x1', total: '24.99', status: 'return_requested' },
  { orderId: 'AMZ-10033', customer: 'Jennifer Lopez', products: 'Collagen Peptides 500g x1', total: '59.99', status: 'shipped' },
  { orderId: 'AMZ-10044', customer: 'Michael Chen', products: 'Magnesium Glycinate x3', total: '74.97', status: 'delivered' },
  { orderId: 'AMZ-10055', customer: 'Emma Wilson', products: 'Probiotic 50B CFU x1', total: '34.99', status: 'pending' }
];
amazonOrders.forEach(o => {
  docs.push({ json: {
    text: `Order ${o.orderId} | Platform: Amazon | Customer: ${o.customer} | Products: ${o.products} | Total: USD ${o.total} | Status: ${o.status}`,
    metadata: { id: `amazon-order-${o.orderId}`, platform: 'amazon', type: 'order', source: 'mock', orderId: o.orderId, customer: o.customer, status: o.status, total: o.total, currency: 'USD' }
  }});
});

const tiktokOrders = [
  { orderId: 'TT-20011', customer: 'Lily Zhang', products: 'Collagen Gummies x2', total: '39.98', status: 'shipped', note: '3-star review packaging damaged' },
  { orderId: 'TT-20022', customer: 'Kevin Park', products: 'Apple Cider Vinegar Gummies x1', total: '19.99', status: 'delivered', note: '5-star' },
  { orderId: 'TT-20033', customer: 'Mia Johnson', products: 'Biotin 10000mcg x2', total: '29.98', status: 'refund_requested', note: '' },
  { orderId: 'TT-20044', customer: 'Ryan Lee', products: 'Ashwagandha 600mg x1', total: '27.99', status: 'delivered', note: '4-star' },
  { orderId: 'TT-20055', customer: 'Sophia Wang', products: 'Elderberry Syrup x3', total: '44.97', status: 'processing', note: '' }
];
tiktokOrders.forEach(o => {
  docs.push({ json: {
    text: `Order ${o.orderId} | Platform: TikTok Shop | Customer: ${o.customer} | Products: ${o.products} | Total: USD ${o.total} | Status: ${o.status}${o.note ? ' | Note: ' + o.note : ''}`,
    metadata: { id: `tiktok-order-${o.orderId}`, platform: 'tiktok', type: 'order', source: 'mock', orderId: o.orderId, customer: o.customer, status: o.status, total: o.total, currency: 'USD' }
  }});
});

const faqs = [
  { id: 'faq-return-policy', category: 'returns', text: 'Return Policy: We accept returns within 30 days of purchase. Items must be unopened and in original condition. Refunds processed within 5-7 business days.' },
  { id: 'faq-shipping', category: 'shipping', text: 'Shipping Policy: Standard shipping 5-7 business days ($4.99). Express shipping 2-3 business days ($12.99). Free standard shipping on orders over $50. We ship to US, Canada, UK, and Australia.' },
  { id: 'faq-product-usage', category: 'usage', text: 'Product Usage: Take supplements with food and water. Do not exceed recommended dosage. Consult your doctor if pregnant, nursing, or on medication.' },
  { id: 'faq-subscription', category: 'subscription', text: 'Subscription: Save 15% with auto-ship every 30/60/90 days. Cancel anytime before next shipment.' },
  { id: 'faq-ingredients', category: 'ingredients', text: 'Ingredients & Allergens: All products are third-party tested, non-GMO, and gluten-free. Some products contain fish (Omega-3), dairy, or soy.' }
];
faqs.forEach(f => {
  docs.push({ json: {
    text: f.text,
    metadata: { id: f.id, platform: 'all', type: 'faq', source: 'policy', category: f.category, status: '', customer: '', total: '' }
  }});
});

return docs;

// 合并 embedding 和原始数据
const items = $input.all();
return items.map(item => ({
  json: {
    embedding: item.json.data[0].embedding,
    text: item.json.text,
    metadata: item.json.metadata
  }
}));

// Aggregate 输出: { data: [{ embedding: [...] }, ...] }
// 原始数据从 Merge All 节点获取（顺序一致）
const embedItems = $input.first().json.data;
const origItems = $('Merge All').all();

const vectors = embedItems.map((emb, idx) => {
  const orig = origItems[idx].json;
  return {
    id: orig.metadata.id,
    values: emb.embedding,
    metadata: {
      text: orig.text,
      ...orig.metadata
    }
  };
});

return [{ json: { vectors } }];

const vectorCount = $json.upsertedCount || $('Build Vectors').first().json.vectors.length;
const allItems = $('Aggregate').first().json.data;

return [{ json: {
  status: 'success',
  inserted: vectorCount,
  breakdown: {
    shopifyOrders: allItems.filter(i => i?.metadata?.type === 'order' && i?.metadata?.platform === 'shopify').length,
    shopifyProducts: allItems.filter(i => i?.metadata?.type === 'product').length,
    amazonOrders: 5,
    tiktokOrders: 5,
    faqDocs: 5
  }
}}];
